from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrdrbQciParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        bts_id = self.enb_ent_config['id']
        num = int(self.mo_num)
        nrdrb_num = num + 1
        self.set_parameter('nrDrbDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRDRB-{nrdrb_num}')

        if num < 6:
            self.set_parameter('qciValueList', f'{num+4}')
        elif num == 6:
            self.set_parameter('qciValueList', '69')
        elif num == 7:
            self.set_parameter('qciValueList', '70')
        elif num == 8:
            self.set_parameter('qciValueList', '79')
